<div class="wrap wpep-wrap" dir="rtl"><div class="wpep-card"><h1>پاسخ‌های آماده پشتیبان</h1><p>پاسخ‌های پرتکرار را بسازید تا پشتیبان با یک کلیک متن را وارد کند.</p><form method="post" style="display:grid;gap:10px;max-width:800px"><input type="hidden" name="_wpnonce" value="<?php echo esc_attr( wp_create_nonce( WPEventPublisher\Tickets::NONCE ) ); ?>"><input name="title" placeholder="عنوان پاسخ آماده" required><textarea name="body" rows="5" placeholder="متن پاسخ آماده" required></textarea><label class="jarchi-checkline"><input type="checkbox" name="add_to_faq" value="1"> افزودن همین پاسخ به سوالات متداول</label><button class="button button-primary" name="jarchi_canned_save" value="1">ذخیره پاسخ آماده</button></form><hr><div class="wpep-ticket-list"><?php foreach ( $items as $i => $item ) : ?><div class="wpep-ticket-row"><span><strong><?php echo esc_html( $item['title'] ?? '' ); ?></strong><small><?php echo esc_html( wp_strip_all_tags( (string) ( $item['body'] ?? '' ) ) ); ?></small></span><form method="post"><input type="hidden" name="_wpnonce" value="<?php echo esc_attr( wp_create_nonce( WPEventPublisher\Tickets::NONCE ) ); ?>"><input type="hidden" name="index" value="<?php echo esc_attr( $i ); ?>"><button class="button" name="jarchi_canned_add_faq" value="1">افزودن به FAQ</button><button class="button" name="jarchi_canned_delete" value="1">حذف</button></form></div><?php endforeach; ?></div></div></div>